gt;&lt;td&gt;44 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broyeur-Dennemis.html&quot; title=&quot;Broyeur d&amp;#39;ennemis&quot;&gt;Broyeur d&#39;ennemis&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;54 212 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td width=&quot;50%&quot;&gt;
